export default {async fetch(request){const path=new URL(request.url).pathname;const name=path==="/"?"/index.html":path;const body=assets[name];if(body===undefined)return new Response("Not found",{status:404});const ext=name.split(".").pop();return new Response(body,{headers:{"Content-Type":({html:"text/html; charset=utf-8",css:"text/css",js:"text/javascript",json:"application/json"})[ext]||"text/plain","X-Content-Type-Options":"nosniff"}})}};
